function drawTorterraContinentTortoise(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 1.8;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.03 * breathSin;
  const sX = 1.0 - 0.015 * breathSin;
  const by = -Math.abs(breathSin) * 2.0;

  const treeSway = Math.sin(t * 2.0) * 2.0;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 36 * (1.0 - 0.15 * breathSin), 8, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Núi đá
  ctx.fillStyle = '#94a3b8';
  ctx.beginPath(); ctx.moveTo(-24, by - 6); ctx.lineTo(-18, by - 24); ctx.lineTo(-10, by - 6); ctx.fill();
  ctx.fillStyle = '#cbd5e1';
  ctx.beginPath(); ctx.moveTo(-16, by - 4); ctx.lineTo(-10, by - 18); ctx.lineTo(-4,  by - 4); ctx.fill();

  // 3. Cây Bonsai
  const bx = 16 + treeSway;
  ctx.fillStyle = '#78350f';
  ctx.beginPath(); ctx.roundRect(bx - 3, by - 14, 6, 16, 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(bx - 6, by - 8); ctx.lineTo(bx + 8, by - 16); ctx.lineTo(bx + 2, by - 6); ctx.fill();
  ctx.fillStyle = '#166534';
  ctx.beginPath(); ctx.arc(bx + 4,  by - 22, 10, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(bx - 6,  by - 18, 8,  0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#22c55e';
  ctx.beginPath(); ctx.arc(bx + 12, by - 16, 7,  0, Math.PI * 2); ctx.fill();

  // 4. Mai rùa
  ctx.fillStyle = '#15803d';
  ctx.beginPath(); ctx.ellipse(0, by + 4, 28 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#22c55e';
  ctx.beginPath(); ctx.ellipse(0, by + 2, 25 * sX, 15 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 5. Viền mai bạc
  ctx.fillStyle = '#cbd5e1';
  ctx.beginPath(); ctx.roundRect(-30, by + 12, 60, 8, 3); ctx.fill();

  // 6. 4 Chân
  ctx.fillStyle = '#9a3412';
  [-26, -10, 6, 18].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 16, 10, 19, 3); ctx.fill();
  });
  ctx.fillStyle = '#ffffff';
  [-24, -20, -8, -4, 8, 12, 20, 24].forEach(x => {
    ctx.beginPath(); ctx.arc(x, by + 34, 2, 0, Math.PI * 2); ctx.fill();
  });

  // 7. Đầu rùa & Mỏ sừng
  ctx.fillStyle = '#16a34a';
  ctx.beginPath(); ctx.ellipse(-24, by + 8, 12, 10, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.moveTo(-34, by + 10); ctx.lineTo(-28, by + 6); ctx.lineTo(-28, by + 14); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(-24, by + 14); ctx.lineTo(-30, by + 18); ctx.lineTo(-20, by + 18); ctx.fill();

  // 8. Mắt đỏ
  if (!blink) {
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.arc(-24, by + 6, 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-25, by + 5, 1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-26, by + 6); ctx.lineTo(-22, by + 6); ctx.stroke();
  }

  ctx.restore();
}
